import { path } from '@servicenow/sdk-build-core'
import * as fs from 'fs'
import { Project } from '../../src'

const projectDir = path.resolve(__dirname, 'out')

describe('Project management tests', () => {
    beforeEach(() => {
        if (fs.existsSync(projectDir)) {
            fs.rmSync(projectDir, { recursive: true })
        }
    })

    test('Create and persist a new project from scratch', async () => {
        const project = new Project({
            rootDir: projectDir,
            config: { scope: 'x_test', scopeId: '12345' },
            packageJson: { name: 'test', version: '0.0.1' },
        })

        const keysFile = project.getFile('src/fluent/generated/keys.ts')
        expect(keysFile).toBeDefined()

        // Try overwriting existing package.json file
        project.addFile({
            path: 'package.json',
            content: JSON.stringify(
                {
                    name: 'changed',
                    version: '2.0.0',
                    scripts: {
                        build: 'now-sdk build',
                    },
                },
                null,
                4
            ),
        })

        project.addFile({
            path: 'src/stuff.json',
            content: JSON.stringify(
                {
                    hello: 'world',
                    foo: 'bar',
                },
                null,
                4
            ),
        })

        // Try overwriting existing Fluent file
        project.addFile({ path: 'src/fluent/index.now.ts', content: '' })
        const indexFile = project.addFile({
            path: 'src/fluent/index.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'
            import stuff from '../stuff.json'

            Record({
                $id: Now.ID[0],
                table: 'sys_user',
                data: {
                    name: 'hello'
                }
            })

            Record({
                $id: Now.ID[1],
                table: 'test',
                data: {
                    value: JSON.stringify(stuff)
                }
            })
            `,
        })

        const helloModule = project.addFile({
            path: 'src/server/hello.js',
            content: 'export function sayHello() { return "Hello" }',
        })

        const helloFluent = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
            import { BusinessRule } from '@servicenow/sdk/core'
            import { sayHello } from '../server/hello'

            BusinessRule({
                $id: Now.ID[2],
                name: 'Say Hello',
                table: 'sys_user',
                when: 'after',
                action: ['update'],
                script: sayHello,
            })
            `,
        })

        project.registerExplicitId('sys_user', 0, '11111')
        project.registerExplicitId('test', 1, '22222')
        project.registerExplicitId('sys_script', 2, '33333')
        project.registerExplicitId('sys_module', 'package_json', '44444')
        project.registerExplicitId('sys_module', 'src_server_hello_js', '55555')
        await project.saveOutput()
        project.save()

        expect(fs.readdirSync(path.resolve(projectDir, 'dist', 'app'))).toHaveLength(2)
        expect(fs.readdirSync(path.resolve(projectDir, 'dist', 'app', 'scope'))).toHaveLength(1)
        expect(fs.readdirSync(path.resolve(projectDir, 'dist', 'app', 'update'))).toHaveLength(6)

        const expectedFiles = {
            [path.resolve(projectDir, 'package.json')]: `
{
    "name": "changed",
    "version": "2.0.0",
    "scripts": {
        "build": "now-sdk build"
    }
}
            `,

            [path.resolve(projectDir, 'now.config.json')]: `
{
    "scope": "x_test",
    "scopeId": "12345"
}
            `,

            [path.resolve(projectDir, 'src', 'stuff.json')]: `
{
    "hello": "world",
    "foo": "bar"
}
            `,

            [path.resolve(projectDir, 'dist', 'app', 'update', 'sys_user_11111.xml')]: `
<?xml version="1.0"?>
<record_update table="sys_user">
  <sys_user action="INSERT_OR_UPDATE">
    <sys_id>11111</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>sys_user_11111</sys_update_name>
    <name>hello</name>
  </sys_user>
</record_update>
            `,

            [path.resolve(projectDir, 'dist', 'app', 'update', 'test_22222.xml')]: `
<?xml version="1.0"?>
<record_update table="test">
  <test action="INSERT_OR_UPDATE">
    <sys_id>22222</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>test_22222</sys_update_name>
    <value>{"hello":"world","foo":"bar"}</value>
  </test>
</record_update>
            `,

            [path.resolve(projectDir, 'dist', 'app', 'update', 'sys_script_33333.xml')]: `
<?xml version="1.0"?>
<record_update table="sys_script">
  <sys_script action="INSERT_OR_UPDATE">
    <sys_id>33333</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>sys_script_33333</sys_update_name>
    <abort_action>false</abort_action>
    <access>package_private</access>
    <action_delete>false</action_delete>
    <action_insert>false</action_insert>
    <action_query>false</action_query>
    <action_update>true</action_update>
    <active>true</active>
    <add_message>false</add_message>
    <advanced>true</advanced>
    <change_fields>false</change_fields>
    <client_callable>false</client_callable>
    <collection>sys_user</collection>
    <condition/>
    <description/>
    <execute_function>false</execute_function>
    <filter_condition/>
    <is_rest>false</is_rest>
    <message/>
    <name>Say Hello</name>
    <order>100</order>
    <priority>100</priority>
    <rest_method/>
    <rest_method_text/>
    <rest_service/>
    <rest_service_text/>
    <rest_variables/>
    <role_conditions/>
    <script><![CDATA[// @fluent-module sayHello;false;x_test/test/0.0.1/src/server/hello.js
// WARNING: This code is generated by the ServiceNow SDK in order to provide
// support for modular JavaScript. Modifications of any kind are likely to
// result in unintended behavior. In most cases, you should edit the source
// file of the module imported below. If you are absolutely certain you want
// to take control of this code, you can remove this comment to prevent the
// SDK from regenerating it. However, you will then be responsible for the
// management of this code in your Fluent file.
const { sayHello } = require('x_test/test/0.0.1/src/server/hello.js');
sayHello(current, previous);]]></script>
    <sys_policy/>
    <template/>
    <when>after</when>
  </sys_script>
</record_update>
            `,

            [path.resolve(projectDir, 'dist', 'app', 'update', 'sys_module_44444.xml')]: `<?xml version="1.0"?>
<record_update table="sys_module">
  <sys_module action="INSERT_OR_UPDATE">
    <sys_id>44444</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>sys_module_44444</sys_update_name>
    <content><![CDATA[{
  "name": "changed",
  "version": "2.0.0",
  "scripts": {
    "build": "now-sdk build"
  }
}]]></content>
    <external_source>false</external_source>
    <path>x_test/test/0.0.1/package.json</path>
    <sys_name>x_test/test/0.0.1/package.json</sys_name>
  </sys_module>
</record_update>`,

            [path.resolve(projectDir, 'dist', 'app', 'update', 'sys_module_55555.xml')]: `<?xml version="1.0"?>
<record_update table="sys_module">
  <sys_module action="INSERT_OR_UPDATE">
    <sys_id>55555</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>sys_module_55555</sys_update_name>
    <content><![CDATA[export function sayHello() { return "Hello" }]]></content>
    <external_source>false</external_source>
    <path>x_test/test/0.0.1/src/server/hello.js</path>
    <sys_name>x_test/test/0.0.1/src/server/hello.js</sys_name>
  </sys_module>
</record_update>`,

            [path.resolve(projectDir, 'dist', 'app', 'scope', 'sys_app_12345.xml')]: `
<?xml version="1.0"?>
<record_update table="sys_app">
  <sys_app action="INSERT_OR_UPDATE">
    <sys_id>12345</sys_id>
    <sys_scope display_value="x_test">12345</sys_scope>
    <sys_update_name>sys_app_12345</sys_update_name>
    <active>true</active>
    <can_edit_in_studio>true</can_edit_in_studio>
    <enforce_license>log</enforce_license>
    <guided_setup_guid/>
    <hide_on_ui>false</hide_on_ui>
    <installed_as_dependency>false</installed_as_dependency>
    <js_level>es_latest</js_level>
    <licensable>true</licensable>
    <license_category>none</license_category>
    <license_model>none</license_model>
    <logo/>
    <menu/>
    <name>test</name>
    <package_json>x_test/test/0.0.1/package.json</package_json>
    <package_resolver_version>1.0.0</package_resolver_version>
    <private>false</private>
    <restrict_table_access>false</restrict_table_access>
    <runtime_access_tracking>permissive</runtime_access_tracking>
    <scope>x_test</scope>
    <scoped_administration>false</scoped_administration>
    <short_description/>
    <source>x_test</source>
    <subscription_entitlement/>
    <trackable>true</trackable>
    <uninstall_blocked>false</uninstall_blocked>
    <user_role/>
    <version>0.0.1</version>
  </sys_app>
</record_update>
            `,

            [path.resolve(projectDir, 'src', 'fluent', 'generated', 'keys.ts')]: keysFile.getContent(),
            [path.resolve(projectDir, 'src', 'fluent', 'index.now.ts')]: indexFile.getContent(),
            [path.resolve(projectDir, 'src', 'fluent', 'hello.now.ts')]: helloFluent.getContent(),
            [path.resolve(projectDir, 'src', 'server', 'hello.js')]: helloModule.getContent(),
        }

        for (const [expectedFilePath, expectedFileContent] of Object.entries(expectedFiles)) {
            expect(fs.existsSync(expectedFilePath)).toBeTruthy()
            expect(fs.readFileSync(expectedFilePath, { encoding: 'utf-8' }).trim()).toBe(expectedFileContent.trim())
        }
    })

    test('reload directory', async () => {
        const project = new Project({
            rootDir: projectDir,
        })
        const getSrcFiles = () =>
            project
                .getFiles()
                .map((file) => file.getPath().substring(projectDir.length + 1))
                .filter((file) => file.startsWith('src'))
        project.addFile({ path: 'src/existing', content: 'test content' })
        await project.save()
        expect(getSrcFiles()).toEqual(['src/fluent/generated/keys.ts', 'src/existing'])

        fs.writeFileSync(path.resolve(projectDir, 'src', 'new-file'), 'new content')
        fs.rmSync(path.resolve(projectDir, 'src', 'fluent', 'generated', 'keys.ts'))
        project.reloadDirectory('src')
        expect(getSrcFiles()).toEqual(['src/existing', 'src/new-file'])
    })

    test('create a project with compilerOptions', async () => {
        const project = new Project({
            rootDir: projectDir,
            config: { scope: 'x_test', scopeId: '12345' },
            packageJson: { name: 'test', version: '0.0.1' },
            compilerOptions: {
                noUnusedLocals: false,
            },
        })

        const keysFile = project.getFile('src/fluent/generated/keys.ts')
        expect(keysFile).toBeDefined()

        const helloFluent = project.addFile({
            path: 'src/fluent/hello.now.ts',
            content: `
            import { Record } from '@servicenow/sdk/core'

            const foo = 'unused var test'

            Record({
                $id: Now.ID['sys-user-record'],
                table: 'sys_user',
                data: {}
            })
            `,
        })

        const diagnostics = await helloFluent.getDiagnostics()
        expect(diagnostics.length).toEqual(0)
    })
})
